import{_ as e,o as a,c as o,ai as _}from"./chunks/framework.scx6l_IK.js";const l=JSON.parse('{"title":"答疑2021-不怕念起只怕觉迟","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/答疑2021-不怕念起只怕觉迟.md","filePath":"60-原文段落/答疑2021-不怕念起只怕觉迟.md","lastUpdated":1778155802000}'),r={name:"60-原文段落/答疑2021-不怕念起只怕觉迟.md"};function p(s,t,u,n,c,d){return a(),o("div",null,[...t[0]||(t[0]=[_('<h1 id="答疑2021-不怕念起只怕觉迟" tabindex="-1">答疑2021-不怕念起只怕觉迟 <a class="header-anchor" href="#答疑2021-不怕念起只怕觉迟" aria-label="Permalink to &quot;答疑2021-不怕念起只怕觉迟&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/14_答疑专辑2021年整理版">14_答疑专辑2021年整理版</a> 切分日期：2026-05-06</p></blockquote><hr><p>**问：**师父好，有时呢，升起一个念头，马上发现不对，然后念头就沉下去或消失了，那么这个觉知就是自性起作用吗？</p><p>**师答：**哦，自性其实没有奥妙的，我们明心见性就是明白你的真心，见到你的本性，我们的本性是什么呢？自古说人之初，性本善，有些人说人之初性本恶，其实不是的，人的本性本来就是没有特别的善，也没有特别的恶，如果我们一个人能够以这种很客观的心态，没有带着特别善，也没有带着特别恶，以这种清净心来看问题，这个状态其实就是明心见性的状态。</p><p>你说了空居士你怎么敢这么说？哎，我哪敢，这六祖说的。六祖在行由品对惠明说的，说&quot;不思善不思恶，正语么时，那个是明上座的本来面目&quot;，&quot;不思善不思恶&quot;就是说：你不要带着一种善的执着，也不要带着恶的执着。譬如&quot;归宗斩蛇&quot;，将这条蛇打死，从五戒的角度是杀生，从这条蛇的性质来说，我不将它打死，他可能等一下会咬伤人……所以说，这个时候你说从杀生的角度说归宗是错的，从总体考虑来说，归宗是对的啊，所以归宗他没有带着个人的什么善恶的这种执着，所以看见了哎呀，还是将这条蛇打死算了吧。所以他这个时候他的心态是属于&quot;不思善不思恶，正语么时，那个是归宗大师的本来面目&quot;啊，所以我们一个人，这个最清净客观的心，就是我们的自性现前的状态。</p><p>那好啦，我们心里有这一个不好的念头升起来，你马上知道了，将这个念头制止，制止，这个严格来说，说是自己的这个自性现前也可以，当然有时候还不一定达到，自性现前对事物的看法可以说是接近绝对的客观，但是我们有时候将不良的念头制止，那个时候有时候也不一定是绝对的客观，有时候也会是一种某方面的主观的习惯也有可能。</p><p>**问：**如果功夫深了，这种不正确的念头就不会升起，直接就是无差别的清净觉知出现吗？</p><p>**师答：**对的对的，就是说普通的时候就&quot;不怕念起，只怕觉迟&quot;，功夫越高深的人，这种乱七八糟的念头就越少，就是心如明镜，就好像这个《六祖坛经》里边说四智：大圆镜智，平等性智，妙观察智，成所作智啊，我也常常说四智其实是三智，是大圆镜智为本体嘛，在具体的应用就是所谓的平等性智，妙观察智，成所作智哈。谢谢大家。</p>',9)])])}const q=e(r,[["render",p]]);export{l as __pageData,q as default};
